"use strict";(globalThis.webpackChunkgrc||=[]).push([[31788],{63358(e){e.exports=JSON.parse('{"citeKey":"cernuda2024jarvis","slug":"cernuda-2024-jarvis-3b52","title":"Jarvis: Towards a Shared, User-Friendly, and Reproducible, I/O Infrastructure.","authors":["J. Cernuda","L. Logan","N. Lewis","S. Byna","X.-H. Sun","A. Kougkas"],"venue":"The International Parallel Data Systems Workshop (PDSW\'24)","type":"Workshop","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"abstract":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters. However, computing environments for developing tools to harness these technologies are not easily available to researchers. This work showcases the need for a new high-pace, heterogeneous I/O research cluster and presents a novel software deployment framework named Jarvis to manage its hardware diversity. Jarvis is an extensible Python framework that allows users to create Packages that deploy, manage, and monitor software, including complex applications (e.g., scientific simulations), support tools (e.g., Darshan, GDB), and storage systems (e.g., Lustre, DAOS). These packages can be combined to form complex deployment Pipelines. To ensure pipelines are portable across hardware, Jarvis defines a novel Resource Graph schema file, which is a snapshot of a cluster\'s machine-specific information. This schema can be queried by Jarvis packages to deploy software across diverse hardware compositions with minimal user effort. Index Terms-deployment, HPC, hardware abstraction, resource management, I/O, Python","hasAbstract":true,"lede":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters.","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-jarvis-3b52.pdf"},"tags":["Deployment","HPC","Hardware Abstraction","I/O","Python","Resource Management"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["iowarp","coeus","chronolog","hermes"],"memberAuthors":["cernuda-jaime","logan-luke","byna-surendra","sun-xian-he","kougkas-anthony"]}')}}]);